function toMin(t){ var p=String(t).split(':'); if(p.length<2) return NaN;
  var h=+p[0], m=+p[1], s=p.length>2?+p[2]:0; if(isNaN(h)||isNaN(m)) return NaN; return h*60+m+s/60; }
function fmt(min){ var total=Math.round(min*60); total=((total%(86400))+86400)%86400;
  var h=Math.floor(total/3600), m=Math.floor((total%3600)/60), s=total%60;
  var r=('0'+h).slice(-2)+':'+('0'+m).slice(-2); if(s) r+=':'+('0'+s).slice(-2); return r; }
function timeAdd(t1, dur){ var a=toMin(t1), b=toMin(dur); if(isNaN(a)||isNaN(b)) return {error:'时间格式须为 HH:MM 或 HH:MM:SS'};
  var r=((a+b)%1440+1440)%1440; return {result:fmt(r), totalMinutes:Math.round(r)}; }
function timeDiff(t1, t2){ var a=toMin(t1), b=toMin(t2); if(isNaN(a)||isNaN(b)) return {error:'时间格式须为 HH:MM'};
  var d=b-a, r=((d%1440)+1440)%1440; return {diff:fmt(r), minutes:Math.round(r), signed:Math.round(d)}; }
var EXPORTS={toMin:toMin, fmt:fmt, timeAdd:timeAdd, timeDiff:timeDiff};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TimeCalcForgePure = EXPORTS; }
